// AttributedOrders Split by model and never summed into one "orders" figure. A view-through
// order and a click-through order are different claims about whether the feed
// works, and adding them asserts they are the same claim.
type AttributedOrders struct {
	Declared    *int64 `json:"declared,omitempty"`
	LastClick   *int64 `json:"last_click,omitempty"`
	Organic     *int64 `json:"organic,omitempty"`
	ViewThrough *int64 `json:"view_through,omitempty"`
}

// AuthorReel The author's view. Carries the failure reason, which the feed representation
// deliberately does not — a rejected vendor who is told only "rejected" has no
// way to fix it, and that is the most common complaint about every content
// platform.
type AuthorReel struct {
	Caption    *string                `json:"caption,omitempty"`
	CreatedAt  *time.Time             `json:"created_at,omitempty"`
	DurationMs nullable.Nullable[int] `json:"duration_ms,omitempty"`
	Failure    nullable.Nullable[struct {
		Code   *string `json:"code,omitempty"`
		Detail *string `json:"detail,omitempty"`
	}] `json:"failure,omitempty"`
	Id openapi_types.UUID `json:"id"`

	// Lqip BlurHash or base64 micro-thumb, inline so the client paints before any fetch resolves.
	Lqip        nullable.Nullable[string]    `json:"lqip,omitempty"`
	PosterKey   nullable.Nullable[string]    `json:"poster_key,omitempty"`
	PreviewKey  nullable.Nullable[string]    `json:"preview_key,omitempty"`
	PublishedAt nullable.Nullable[time.Time] `json:"published_at,omitempty"`

	// State The reel lifecycle. Transitions are enforced in one place server-side; a
	// client should treat any state it does not recognise as "still processing".
	State      ReelState            `json:"state"`
	Tags       *[]string            `json:"tags,omitempty"`
	Visibility AuthorReelVisibility `json:"visibility"`
}

// AuthorReelVisibility defines model for AuthorReel.Visibility.
type AuthorReelVisibility string

